// oxlint-disable no-unused-vars -- the scoped specimen preserves hook ordering from its source
import { useEffect, useState } from "react";
import { SectionPage, Specimen } from "glass-ux-docs-kit/react";
import { pixelsToRgba8 } from "glass-ux-image/core";
import { Filmstrip, type OpenPicture } from "glass-ux-image/panels/filmstrip";
import { useImageEditor, useSessionState } from "glass-ux-image/react";
import type { EditorSession } from "glass-ux-image/session";
import { develop } from "glass-ux-image/tools/develop";

const photo = `${import.meta.env.BASE_URL}sample.png`;

// One open picture with a develop look applied when it opens.
function useLook(look: Record<string, number>) {
  const editor = useImageEditor({ source: photo, tools: [develop] });
  const { status } = useSessionState(editor);
  useEffect(() => {
    if (status === "ready" && Object.keys(look).length && !editor.state.canUndo)
      editor.run("edit.apply", { filters: { develop: look } });
  }, [editor, status, look]);
  return editor;
}

// Thumbnails are the host's. This one is a small JPEG that follows the session's edits.
function useThumbnail(editor: EditorSession) {
  const { status, recipe } = useSessionState(editor);
  const [url, setUrl] = useState<string>();
  useEffect(() => {
    if (status !== "ready") return;
    let live = true;
    void editor
      .readPreview(240)
      .then((pixels) => {
        if (!live) return;
        const canvas = document.createElement("canvas");
        canvas.width = pixels.width;
        canvas.height = pixels.height;
        const rgba = new Uint8ClampedArray(pixelsToRgba8(pixels));
        canvas
          .getContext("2d")!
          .putImageData(new ImageData(rgba, pixels.width, pixels.height), 0, 0);
        setUrl(canvas.toDataURL("image/jpeg", 0.85));
      })
      .catch(() => {});
    return () => {
      live = false;
    };
  }, [editor, status, recipe]);
  return url;
}

const original = {};
const warm = { exposure: 0.25, temperature: 40 };
const mono = { saturation: -100, contrast: 25 };

function FilmstripSample() {
  const editors = [useLook(original), useLook(warm), useLook(mono)] as const;
  const thumbnails = [useThumbnail(editors[0]), useThumbnail(editors[1]), useThumbnail(editors[2])];
  const pictures: OpenPicture[] = [
    { id: "original", label: "Original", editor: editors[0], thumbnail: thumbnails[0] },
    { id: "warm", label: "Warm", editor: editors[1], thumbnail: thumbnails[1] },
    { id: "mono", label: "Black and white", editor: editors[2], thumbnail: thumbnails[2] },
  ];
  const [selected, setSelected] = useState("original");
  return (
    <div className="flex w-full max-w-xl flex-col gap-3">
      <Filmstrip pictures={pictures} selectedId={selected} onSelectedIdChange={setSelected} />
      <output aria-live="polite" className="type-caption text-fg-muted">
        Selected: {pictures.find((picture) => picture.id === selected)?.label}
      </output>
    </div>
  );
}

export default function Section() {
  return (
    <SectionPage>
      <Specimen
        title="Open pictures"
        description="One thumbnail for each open picture, here three edits of the same photo. It scrolls sideways and the arrow keys move between pictures. Choosing one only reports it: the host switches the editor."
        specimenKey="filmstrip:default:0"
      >
        <div data-live-demo="filmstrip" className="w-full">
          <FilmstripSample />
        </div>
      </Specimen>
    </SectionPage>
  );
}
